WITH recent_products AS (SELECT * FROM products WHERE launch_date <= '2025-09-01' AND ARRAY_CONTAINS(tags, 'bestseller')), summary AS (SELECT CASE WHEN brand IN ('Stark', 'Acme') THEN 'group_a' ELSE 'other' END AS brand_group, MAX(stock_qty) AS max_stock_qty, ROUND(STDDEV(cost), 2) AS stddev_cost FROM recent_products GROUP BY CASE WHEN brand IN ('Stark', 'Acme') THEN 'group_a' ELSE 'other' END) SELECT brand_group, stddev_cost FROM summary WHERE max_stock_qty > 110 ORDER BY stddev_cost DESC;
